import {test,expect} from '@playwright/test';
import {createBlankStoryProject} from '../../packages/runtime-core/src/authoring';
import {confirmAuthoringImport} from './authoring-file';
test.beforeEach(async({page})=>{await page.addInitScript(()=>sessionStorage.setItem('knolstory-fullscreen-offered-v1','1'));});

for(const viewport of [{width:360,height:740},{width:800,height:1100}])test(`keyboard gives basic writing space to the current image and text ${viewport.width}`,async({page})=>{
 await page.setViewportSize(viewport);
 await page.route('**/api/**',r=>r.abort());
 await page.route('**/runtime/**',r=>r.abort());
 await page.goto('/?view=editor');
 const input=page.locator('[data-current-cut] textarea').first();
 await expect(input).toBeVisible();
 const draft=await input.inputValue();
 await input.focus();
 await page.evaluate(()=>{
  Object.defineProperty(visualViewport!,'height',{configurable:true,value:350});
  visualViewport!.dispatchEvent(new Event('resize'));
 });
 const shell=page.locator('main[data-keyboard-occluded=true]');
 await expect(shell).toBeVisible();
 await expect(page.getByRole('complementary',{name:'이전 컷과 장 탐색'})).toBeHidden();
 await expect(page.getByRole('complementary',{name:'다음 컷과 참고 정보'})).toBeHidden();
 await expect(page.locator('[data-stacked-context]')).toBeHidden();
 await expect(page.locator('[data-additional-dock]')).toBeHidden();
 await expect(page.getByRole('group',{name:'현재 컷의 화자',exact:true})).toBeHidden();
 await expect(input).toBeVisible();
 const rect=await input.boundingBox();
 expect(rect!.height).toBeGreaterThanOrEqual(72);
 expect(rect!.y+rect!.height).toBeLessThanOrEqual(351);
 await expect(input).toBeFocused();
 await expect(input).toHaveValue(draft);
 const previous=page.getByRole('button',{name:'이전 컷 편집',exact:true});
 const next=page.getByRole('button',{name:'다음 컷 편집',exact:true});
 await expect(previous).toBeDisabled();
 await expect(next).toBeVisible();
 const nextRect=await next.boundingBox();
 expect(nextRect!.width).toBeGreaterThanOrEqual(44);
 await input.dispatchEvent('compositionstart',{data:''});
 await next.click();
 await expect(input).toHaveValue(draft);
 await input.dispatchEvent('compositionend',{data:''});
 await expect(input).toBeFocused();
 await expect(input).not.toHaveValue(draft);
 await previous.click();
 await expect(input).toBeFocused();
 await expect(input).toHaveValue(draft);
 await page.evaluate(()=>{
  delete (visualViewport as unknown as {height?:number}).height;
  visualViewport!.dispatchEvent(new Event('resize'));
 });
 await expect(page.locator('main[data-keyboard-occluded=false]')).toBeVisible();
 await expect(page.getByRole('complementary',{name:'다음 컷과 참고 정보'})).toBeVisible();
 await expect(page.getByRole('group',{name:'현재 컷의 화자',exact:true})).toBeVisible();
 await expect(input).toHaveValue(draft);
});

test('short phone landscape exposes image, text and arrows without opening the keyboard on navigation',async({browser})=>{
 const context=await browser.newContext({viewport:{width:748,height:259},screen:{width:780,height:360},hasTouch:true});
 await context.addInitScript(()=>sessionStorage.setItem('knolstory-fullscreen-offered-v1','1'));const page=await context.newPage();await page.route('**/api/**',r=>r.abort());await page.route('**/runtime/**',r=>r.abort());await page.goto('/?view=editor');
 await expect(page.locator('[data-phone-editor=true]')).toBeVisible();
 const input=page.locator('[data-current-cut] textarea').first(),draft=await input.inputValue();
 const rect=await input.boundingBox();expect(rect!.height).toBeGreaterThan(80);expect(rect!.y+rect!.height).toBeLessThanOrEqual(260);
 const next=page.getByRole('button',{name:'다음 컷 편집',exact:true}),previous=page.getByRole('button',{name:'이전 컷 편집',exact:true});await next.click();await expect(input).not.toHaveValue(draft);await expect(input).not.toBeFocused();await previous.click();await expect(input).toHaveValue(draft);
 await expect(input).toHaveAttribute('readonly','');
 await expect(page.getByText('글을 수정하려면 휴대폰을 세로로 돌려 주세요.',{exact:true})).toBeVisible();
 await page.setViewportSize({width:390,height:844});
 await expect(input).not.toHaveAttribute('readonly','');
 await input.fill(draft+' 세로에서 수정');
 await expect(input).toHaveValue(draft+' 세로에서 수정');
 await input.fill(draft);
 await expect(input).toHaveValue(draft);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await context.close();
});

