 await page.getByText('1컷 음향 수정',{exact:true}).click();await page.getByRole('combobox',{name:'컷 배경음 동작',exact:true}).selectOption('play');
 const field=page.getByRole('spinbutton',{name:'컷 배경음 서서히 크게 시작 (초)',exact:true}),next=page.getByRole('spinbutton',{name:'컷 배경음 기존 소리 사라짐 (초)',exact:true});
 const first=await field.boundingBox(),second=await next.boundingBox();expect(second!.y).toBeGreaterThanOrEqual(first!.y+first!.height);
 await field.focus();await page.evaluate(()=>{Object.defineProperty(visualViewport!,'height',{configurable:true,value:286});visualViewport!.dispatchEvent(new Event('resize'));});
 await expect(page.locator('main[data-keyboard-occluded=true]')).toBeVisible();await expect(field).toBeFocused();await expect.poll(async()=>{const r=await field.boundingBox();return !!r&&r.y>=0&&r.y+r.height<=287;}).toBe(true);
