test('editor fullscreen hides browser navigation while keeping preparation dialogs reachable',async({page})=>{
 await page.setViewportSize({width:390,height:844});await page.route('**/api/**',r=>r.abort());await page.route('**/runtime/**',r=>r.abort());await page.goto('/?view=editor');await expect(page.getByTestId('save-status')).toHaveText('임시 보관됨');const before=await page.evaluate(()=>JSON.parse(localStorage.getItem('knolstory-next-workspace-v1')!).document.project);
 await page.locator('[data-work-menu]>summary').click();await page.getByRole('button',{name:'전체 화면',exact:true}).click();await expect.poll(()=>page.evaluate(()=>document.fullscreenElement===document.documentElement)).toBe(true);await page.locator('[data-work-menu]>summary').click();await expect(page.getByRole('button',{name:'전체 화면 해제',exact:true})).toBeVisible();await page.getByRole('button',{name:'작품 정보·표지',exact:true}).click();await page.getByRole('button',{name:'책 표지 편집',exact:true}).click();const dialog=page.getByRole('dialog',{name:'내 책 표지 꾸미기',exact:true});await expect(dialog).toBeVisible();expect(await dialog.evaluate(e=>document.fullscreenElement!.contains(e))).toBe(true);await dialog.getByRole('button',{name:'취소',exact:true}).click();await page.getByRole('button',{name:'현재 컷으로 돌아가기',exact:true}).click();await page.locator('[data-work-menu]>summary').click();await page.getByRole('button',{name:'전체 화면 해제',exact:true}).click();await expect.poll(()=>page.evaluate(()=>document.fullscreenElement===null)).toBe(true);expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('knolstory-next-workspace-v1')!).document.project)).toEqual(before);
});

test('phone entry offers fullscreen once per tab and settings remain available after declining',async({browser})=>{
 const context=await browser.newContext({viewport:{width:390,height:844},screen:{width:390,height:844},hasTouch:true});const page=await context.newPage();await page.route('**/api/**',r=>r.abort());await page.route('**/runtime/**',r=>r.abort());await page.goto('/?view=editor');const offer=page.getByRole('dialog',{name:'휴대폰 전체 화면 안내',exact:true});await expect(offer).toBeVisible();await expect(page.getByTestId('save-status')).toHaveText('임시 보관됨');const before=await page.evaluate(()=>JSON.parse(localStorage.getItem('knolstory-next-workspace-v1')!).document.project);await offer.getByRole('button',{name:'지금은 그대로',exact:true}).click();expect(await page.evaluate(()=>document.fullscreenElement)).toBeNull();await page.reload();await expect(page.getByTestId('save-status')).toHaveText('임시 보관됨');await expect(offer).toHaveCount(0);await page.locator('[data-work-menu]>summary').click();await page.getByRole('button',{name:'전체 화면',exact:true}).click();await expect.poll(()=>page.evaluate(()=>document.fullscreenElement===document.documentElement)).toBe(true);expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('knolstory-next-workspace-v1')!).document.project)).toEqual(before);await page.evaluate(()=>document.exitFullscreen());await context.close();
});

