 const text=page.getByRole('textbox',{name:'선택지 1 문구',exact:true});await text.focus();await page.evaluate(()=>{Object.defineProperty(visualViewport!,'height',{configurable:true,value:350});visualViewport!.dispatchEvent(new Event('resize'));});await expect(page.locator('main[data-keyboard-occluded=true]')).toBeVisible();await expect.poll(async()=>{const r=await text.boundingBox();return !!r&&r.y>=0&&r.y+r.height<=351;}).toBe(true);await expect.poll(()=>text.evaluate(e=>{const r=e.getBoundingClientRect();return e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2));})).toBe(true);await text.fill('함께 도와준다');await text.blur();await page.evaluate(()=>{delete (visualViewport as unknown as {height?:number}).height;visualViewport!.dispatchEvent(new Event('resize'));});
