 const base=createBlankStoryProject({id:'opacity-save',chapterId:'ch',lineId:'cut'}),project={...base,lines:base.lines.map(line=>({...line,text:'지켜야 할 원고',inheritActors:false,stageComposition:{leftActors:[{key:'actor',assetId:'seonnyeo.character.M01-base'}],rightActors:[]}}))};await page.route('**/api/**',r=>r.abort());await page.route('**/runtime/**',r=>r.abort());await page.goto('/?view=editor');await expect(page.getByTestId('save-status')).toHaveText('임시 보관됨');const menu=page.locator('[data-work-menu]');await menu.locator(':scope>summary').click();await page.getByLabel('작품 파일 가져오기',{exact:true}).setInputFiles({name:'opacity.knolstory',mimeType:'application/json',buffer:Buffer.from(JSON.stringify({documentType:'story-maker-project',schemaVersion:8,savedAt:'2026-10-27T00:00:00.000Z',appVersion:'test',project}))});await confirmAuthoringImport(page);if(!await menu.evaluate(n=>(n as HTMLDetailsElement).open))await menu.locator(':scope>summary').click();await page.getByText('편집 설정',{exact:true}).click();await page.getByRole('checkbox',{name:'연출 편집 사용',exact:true}).check();await page.getByLabel('편집화면 선택',{exact:true}).selectOption('direction');await page.getByText('1컷 연출 수정',{exact:true}).click();await page.getByLabel('조정할 연출',{exact:true}).selectOption('actors');const input=page.getByLabel('왼쪽 인물 전체 보이는 정도 (%)',{exact:true}),before=await page.evaluate(()=>JSON.parse(localStorage.getItem('knolstory-next-workspace-v1')!).document.project);
 await input.fill('120');await input.press('ControlOrMeta+s');expect(await page.evaluate(()=>(window as unknown as {opacityFile:{writes:number}}).opacityFile.writes)).toBe(0);await expect(input).toHaveAttribute('aria-invalid','true');await expect(input).toBeFocused();expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('knolstory-next-workspace-v1')!).document.project)).toEqual(before);
 await input.fill('75');await input.press('ControlOrMeta+s');await expect.poll(()=>page.evaluate(()=>(window as unknown as {opacityFile:{writes:number}}).opacityFile.writes)).toBe(1);await expect(input).toBeFocused();const result=await page.evaluate(()=>(window as unknown as {opacityFile:{contents:string}}).opacityFile.contents);expect(JSON.parse(result).document.project.lines[0].presentation.actors.left.opacity).toBe(.75);
